mapper.select:
SELECT drive_id, hour_start, observed_seconds, inattention_count, drowsiness_count, distance_meters
FROM drive_hourly_stats
WHERE user_id    = #{userId}
  AND hour_start >= #{from}
  AND hour_start <  #{to}

SELECT d.drive_id, d.started_at, d.ended_at, d.observed_seconds, d.distance_meters,
       d.inattention_count, d.drowsiness_count
FROM drives d
WHERE d.drive_id IN (
    SELECT s.drive_id
    FROM drive_hourly_stats s
    WHERE s.user_id    = #{userId}
      AND s.hour_start >= #{from}
      AND s.hour_start <  #{to}
      AND s.observed_seconds > 0
)
ORDER BY d.started_at DESC, d.drive_id DESC
